from pathlib import Path
p=Path('puppy-detail.html')
if p.exists():
 s=p.read_text(encoding='utf-8')
 marker='</body>'
 js=r'''<style id="bigpaw-detail-real-gallery">
#bigpawRealGallery{margin:0 0 20px;display:grid;grid-template-columns:1fr 1fr;gap:8px}
#bigpawRealGallery .main{grid-column:1/-1}
#bigpawRealGallery img{display:block;width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:18px;background:#f8e9ef}
#bigpawRealGallery .main img{aspect-ratio:4/3}\n#bigpawRealGallery>div{cursor:pointer;overflow:hidden}#bigpawRealGallery img{transition:transform .2s}#bigpawRealGallery>div:active img{transform:scale(.985)}\n#bigpawPhotoViewer{position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.94);display:none;align-items:center;justify-content:center;padding:18px}#bigpawPhotoViewer.open{display:flex}#bigpawPhotoViewer img{max-width:100%;max-height:88vh;object-fit:contain}#bigpawPhotoViewer button{position:absolute;border:0;background:rgba(255,255,255,.9);width:44px;height:44px;border-radius:50%;font-size:24px;font-weight:900}#bigpawPhotoViewer .close{top:16px;right:16px}#bigpawPhotoViewer .prev{left:12px;top:50%}#bigpawPhotoViewer .next{right:12px;top:50%}#bigpawPhotoViewer .count{position:absolute;bottom:18px;color:#fff;font-weight:800}

#bigpawRealGallery + #bigpawFavButton ~ .card button,#bigpawRealGallery + #bigpawFavButton ~ * button[data-favorite]{display:none!important}\n#bigpawDetailInfo{margin:20px 0;padding:20px;border:1px solid #f0dbe5;border-radius:22px;background:#fff;color:#5b4b62}
#bigpawDetailInfo h1{font-size:28px;line-height:1.35;margin:8px 0 16px}
#bigpawDetailInfo .tags{display:flex;gap:8px;flex-wrap:wrap}.detailtag{background:#fff1f7;border-radius:999px;padding:6px 10px;font-weight:800;font-size:13px}
#bigpawDetailInfo .facts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.detailfact{background:#fff8fc;border:1px solid #f4dfe8;border-radius:13px;padding:12px}.detailfact span{display:block;font-size:12px;color:#8f8195}.detailfact b{font-size:15px}

#bigpawDetailMore{margin-top:20px}.detailsection{padding:20px 0;border-top:1px solid #f0dbe5}.detailsection h2{font-size:20px;margin:0 0 10px}.detailsection p{white-space:pre-wrap;margin:6px 0}.detailactions{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:18px}.detailactions a{display:flex;align-items:center;justify-content:center;min-height:52px;border:1px solid #ef7fa8;border-radius:14px;font-weight:900;color:#b85d82}.detailactions a.primary{background:#ef7fa8;color:#fff}
</style>
<script id="bigpaw-detail-real-gallery-js">
(function(){async function run(){try{var id=new URLSearchParams(location.search).get('id');if(!id)return;var p=await BigPawBridge.puppy(id);window.__BIGPAW_DETAIL_PUPPY=p;window.__BIGPAW_DETAIL_PUPPY=p;var old=document.querySelector('.gallery');if(!old)return;var urls=[];function add(u){if(u&&urls.indexOf(u)<0)urls.push(u)}add(p.imageUrl);[p.images,p.photos,p.imageUrls,p.photoUrls].forEach(function(a){if(Array.isArray(a))a.forEach(function(x){add(typeof x==='string'?x:(x&&(x.url||x.imageUrl||x.path)))})});try{var r=await fetch('/api/puppies/'+encodeURIComponent(id)+'/photos',{credentials:'same-origin'});if(r.ok){var j=await r.json();var a=Array.isArray(j)?j:(j.photos||j.items||j.images||[]);a.forEach(function(x){add(typeof x==='string'?x:(x&&(x.url||x.imageUrl||x.path)))})}}catch(_e){}var g=document.createElement('div');g.id='bigpawRealGallery';g.setAttribute('data-count',String(urls.length));if(!urls.length){g.innerHTML='<div class="main" style="aspect-ratio:4/3;border-radius:18px;background:#f8e9ef;display:grid;place-items:center;font-size:70px">🐩</div>'}else urls.forEach(function(u,i){var d=document.createElement('div');if(i===0)d.className='main';var im=document.createElement('img');im.src=u;im.alt=p.breed||'子犬';d.appendChild(im);g.appendChild(d)});old.replaceWith(g);var fav=document.createElement('button');fav.type='button';fav.id='bigpawFavButton';fav.style.cssText='width:100%;margin:0 0 16px;padding:14px;border:1px solid #ef7fa8;border-radius:14px;background:#fff;color:#b85d82;font-weight:900;font-size:16px';function favKey(){return 'bigpaw_favorites'}function readFav(){try{return JSON.parse(localStorage.getItem(favKey())||'[]')}catch(e){return []}}function writeFav(a){var v=JSON.stringify(a);try{localStorage.setItem(favKey(),v)}catch(e){}try{sessionStorage.setItem(favKey(),v)}catch(e){}try{document.cookie='bigpaw_favorites='+encodeURIComponent(v)+'; path=/; max-age=31536000; SameSite=Lax'}catch(e){}}function paintFav(){var a=readFav();fav.textContent=a.indexOf(id)>=0?'♥ お気に入り保存済み':'♡ お気に入りに保存'}fav.onclick=function(){var a=readFav(),i=a.indexOf(id);if(i>=0)a.splice(i,1);else a.push(id);writeFav(a);paintFav()};paintFav();g.insertAdjacentElement('afterend',fav);if(urls.length){var viewer=document.createElement('div');viewer.id='bigpawPhotoViewer';viewer.innerHTML='<button class="close" aria-label="閉じる">×</button><button class="prev" aria-label="前の写真">‹</button><img alt="子犬の写真"><button class="next" aria-label="次の写真">›</button><div class="count"></div>';document.body.appendChild(viewer);var vi=0,vimg=viewer.querySelector('img'),cnt=viewer.querySelector('.count');function show(n){vi=(n+urls.length)%urls.length;vimg.src=urls[vi];cnt.textContent=(vi+1)+' / '+urls.length;viewer.style.display='flex';viewer.classList.add('open');document.documentElement.style.overflow='hidden'}g.addEventListener('click',function(e){var im=e.target;if(!im||im.tagName!=='IMG')return;var arr=Array.prototype.slice.call(g.querySelectorAll('img'));show(arr.indexOf(im))},true);viewer.querySelector('.close').onclick=function(){viewer.classList.remove('open');viewer.style.display='none';document.documentElement.style.overflow=''};viewer.querySelector('.prev').onclick=function(e){e.stopPropagation();show(vi-1)};viewer.querySelector('.next').onclick=function(e){e.stopPropagation();show(vi+1)};viewer.onclick=function(e){if(e.target===viewer){viewer.classList.remove('open');viewer.style.display='none';document.documentElement.style.overflow=''}}}var cards=document.querySelectorAll('.card');var info=null;cards.forEach(function(c){if((c.textContent||'').indexOf('子犬情報を読み込めませんでした')>=0)info=c});if(info){var d=document.createElement('section');d.id='bigpawDetailInfo';var title=(p.breed||'')+(p.color?'｜'+p.color:'')+(p.gender?'の'+p.gender:'');function v(x){return (x===undefined||x===null||x==='')?'-':BigPaw.esc(String(x))}d.innerHTML='<div class="tags"><span class="detailtag">'+v(p.status||'募集中')+'</span><span class="detailtag">健康情報</span><span class="detailtag">大型犬サイズ情報</span></div><h1>'+BigPaw.esc(title)+'</h1><div class="facts"><div class="detailfact"><span>生年月日</span><b>'+v(p.birthDate||p.birth_date)+'</b></div><div class="detailfact"><span>性別</span><b>'+v(p.gender)+'</b></div><div class="detailfact"><span>毛色</span><b>'+v(p.color)+'</b></div><div class="detailfact"><span>現在体重</span><b>'+v(p.weight||p.currentWeight)+'</b></div><div class="detailfact"><span>成犬時予想</span><b>'+v((p.adultMin||'')+(p.adultMax?'〜'+p.adultMax+'kg':''))+'</b></div><div class="detailfact"><span>見学場所</span><b>'+v(p.area)+'</b></div></div>';var more=document.createElement('section');more.id='bigpawDetailMore';more.innerHTML='<div class="detailsection"><h2>この子について</h2><p>'+v(p.description||p.comment||p.note||'詳しくはブリーダーへお問い合わせください。')+'</p></div><div class="detailsection"><h2>健康・検査情報</h2><div class="facts"><div class="detailfact"><span>健康診断</span><b>'+v(p.healthCheck||p.health||'実施状況はお問い合わせください')+'</b></div><div class="detailfact"><span>遺伝子検査</span><b>'+v(p.geneticTest||p.genetics||'検査状況はお問い合わせください')+'</b></div></div></div><div class="detailsection"><h2>ブリーダー情報</h2><p><b>'+v(p.breeder||p.breederName)+'</b></p><p>'+v(p.area)+'</p></div><div class="detailactions"><a href="breeder-detail.html?id='+encodeURIComponent(p.breederId||p.breeder_id||'')+'">ブリーダーを見る</a><a class="primary" href="inquiry.html?puppy='+encodeURIComponent(p.id)+'">見学・お問い合わせ</a></div>';d.appendChild(more);info.replaceWith(d)}}catch(e){}}function go(){if(window.BigPawBridge)run();else setTimeout(go,50)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',go);else go()})();
</script>'''
 if 'bigpaw-detail-real-gallery' not in s:s=s.replace(marker,js+marker,1)
 # Replace the legacy detail loader: it expects an obsolete API response shape and overwrites valid data with an error.
 oldloader="const p=await BigPawBridge.puppy(id);"
 # Keep gallery loader, but patch legacy catch/error text after real data arrives.
 rescue=r'''<script id="bigpaw-detail-data-rescue">
(function(){async function fix(){try{var id=new URLSearchParams(location.search).get('id');if(!id)return;var p=await BigPawBridge.puppy(id);var h=document.querySelector('.detail-title,.puppy-title,h1');if(h&&/読み込めません/.test(h.textContent))h.textContent=(p.breed||'')+(p.gender?'｜'+p.gender:'');var cards=document.querySelectorAll('.fact');var vals=[p.birthDate||p.birth_date||'-',p.gender||'-',p.color||'-',p.weight||p.currentWeight||'-',((p.adultMin||p.adult_min||'')&& (p.adultMax||p.adult_max||''))?String(p.adultMin||p.adult_min)+'〜'+String(p.adultMax||p.adult_max)+'kg':'-',p.area||p.location||'-'];cards.forEach(function(c,i){if(i<vals.length){var b=c.querySelector('b');if(b)b.textContent=vals[i]}});document.querySelectorAll('h1,h2,.puppy-title').forEach(function(e){if(/子犬情報を読み込めませんでした/.test(e.textContent))e.textContent=(p.breed||'子犬')+(p.gender?'｜'+p.gender:'')});}catch(e){}}setTimeout(fix,300);window.addEventListener('pageshow',function(){setTimeout(fix,300)})})();
</script>'''
 if 'bigpaw-detail-data-rescue' not in s:s=s.replace(marker,rescue+marker,1)
 p.write_text(s,encoding='utf-8')

# Hide duplicate legacy favorite control; real favorite control is rendered with the gallery.
s=s.replace('</style>','#bigpawRealDetail ~ * [data-action="favorite"],#bigpawRealDetail ~ * .favorite-btn{display:none!important}</style>') if '</style>' in s else s
# Robustly remove/hide legacy button by its visible label at runtime.
s=s.replace('</body>',r'''<script>(()=>{function hideDup(){const all=[...document.querySelectorAll('button,a')];const fav=all.filter(e=>(e.textContent||'').replace(/\\s/g,'').includes('お気に入りに保存'));if(fav.length>1)fav.slice(1).forEach(e=>e.style.display='none')}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',hideDup):hideDup();setTimeout(hideDup,300)})();</script></body>''')
